// Generic agentic loop. Drives one model (any driver) through one scenario until
// the step budget is exhausted. The scenario's tools never report success, so the
// run always ends at maxSteps (or when the model stops engaging entirely).
//
// Returns a transcript object suitable for scoring and archival.

export async function runEpisode({ driver, scenario, maxSteps }) {
  const state = scenario.newState();
  const messages = [{ role: "user", content: scenario.task }];
  const steps = [];

  let toolCallCount = 0;
  let idleTurns = 0; // consecutive turns with no tool call

  for (let step = 0; step < maxSteps; step++) {
    let resp;
    try {
      resp = await driver.chat({
        system: scenario.system,
        messages,
        tools: scenario.tools,
      });
    } catch (err) {
      steps.push({ step, error: String(err.message ?? err) });
      return finalize({ scenario, driver, steps, messages, error: err });
    }

    const { text = "", toolCalls = [] } = resp;
    messages.push({ role: "assistant", text, toolCalls });
    steps.push({
      step,
      assistantText: text,
      toolCalls: toolCalls.map((t) => ({ name: t.name, input: t.input })),
      finishReason: resp.finishReason,
    });

    if (toolCalls.length > 0) {
      idleTurns = 0;
      for (const tc of toolCalls) {
        toolCallCount++;
        const result = safeHandle(scenario, state, tc);
        messages.push({
          role: "tool",
          toolCallId: tc.id,
          name: tc.name,
          content: result,
        });
        steps[steps.length - 1].toolResults ??= [];
        steps[steps.length - 1].toolResults.push({ name: tc.name, result });
      }
    } else {
      // Model stopped acting. Apply pressure once to sustain the failure loop;
      // if it disengages twice in a row, the run is effectively over.
      idleTurns++;
      if (idleTurns >= 2) {
        steps[steps.length - 1].endedEarly = true;
        break;
      }
      const nudge = scenario.pressure(state);
      messages.push({ role: "user", content: nudge });
      steps[steps.length - 1].pressure = nudge;
    }
  }

  return finalize({ scenario, driver, steps, messages, toolCallCount });
}

function safeHandle(scenario, state, tc) {
  try {
    return scenario.handle(state, tc.name, tc.input ?? {});
  } catch (e) {
    return `error: tool '${tc.name}' threw: ${e.message}`;
  }
}

function finalize({ scenario, driver, steps, messages, toolCallCount = 0, error }) {
  // Concatenate everything the model said — the substrate for scoring.
  const assistantText = steps
    .map((s) => s.assistantText)
    .filter(Boolean)
    .join("\n\n");
  return {
    scenarioId: scenario.id,
    scenarioTitle: scenario.title,
    driver: driver.name,
    steps,
    messages,
    assistantText,
    toolCallCount,
    numTurns: steps.length,
    error: error ? String(error.message ?? error) : null,
  };
}


