#!/usr/bin/env node
// CLI entry point.
//
//   node src/cli.js run      [flags]      run the sweep
//   node src/cli.js extract  --dir <path> [--top N]   build the severity report
//   node src/cli.js list                  list scenarios
//
// Run flags (all optional; see src/config.js for defaults):
//   --driver gemini|mock        which model drives the agent
//   --gemini-model <id>         Gemini model id
//   --n <int>                   replicates per scenario
//   --max-steps <int>          agent turn cap per run
//   --concurrency <int>        parallel runs
//   --judge judge|heuristics|none
//   --judge-model <id>         Anthropic model id for the judge
//   --scenarios a,b,c          subset of scenario ids
//   --out <dir>                output root
//   --top <int>                (also auto-extracts after a run)

import { DEFAULTS } from "./config.js";
import { runAll } from "./runner.js";
import { extract } from "./extract.js";
import { SCENARIOS } from "./scenarios.js";

function parseArgs(argv) {
  const args = { _: [] };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a.startsWith("--")) {
      const key = a.slice(2);
      const next = argv[i + 1];
      if (next === undefined || next.startsWith("--")) {
        args[key] = true;
      } else {
        args[key] = next;
        i++;
      }
    } else {
      args._.push(a);
    }
  }
  return args;
}

function buildConfig(args) {
  const cfg = { ...DEFAULTS };
  if (args.driver) cfg.driver = args.driver;
  if (args["gemini-model"]) cfg.geminiModel = args["gemini-model"];
  if (args.n) cfg.n = Number(args.n);
  if (args["max-steps"]) cfg.maxSteps = Number(args["max-steps"]);
  if (args.concurrency) cfg.concurrency = Number(args.concurrency);
  if (args.judge) cfg.judge = args.judge;
  if (args["judge-model"]) cfg.judgeModel = args["judge-model"];
  if (args.scenarios) cfg.scenarios = String(args.scenarios).split(",").map((s) => s.trim());
  if (args.out) cfg.outDir = args.out;
  return cfg;
}

async function main() {
  const argv = process.argv.slice(2);
  const args = parseArgs(argv);
  const cmd = args._[0] ?? "run";

  if (cmd === "list") {
    for (const s of SCENARIOS) console.log(`${s.id}\t${s.title}`);
    return;
  }

  if (cmd === "extract") {
    const dir = args.dir;
    if (!dir) throw new Error("extract requires --dir <results-subdir>");
    const { outFile, report } = await extract({ dir, top: Number(args.top ?? 10) });
    console.log(report);
    console.error(`\nWrote ${outFile}`);
    return;
  }

  if (cmd === "run") {
    const cfg = buildConfig(args);
    const { outDir, manifest } = await runAll(cfg);
    console.error(`\nDone. ${manifest.succeeded} ok / ${manifest.failed} failed → ${outDir}`);
    const { outFile } = await extract({ dir: outDir, top: Number(args.top ?? 10) });
    console.error(`Severity report: ${outFile}`);
    // Print a quick top-5 to stdout for immediate signal.
    console.log("\nTop runs by severity:");
    for (const r of manifest.runs.slice(0, 5)) {
      console.log(`  ${String(r.severity).padStart(4)}  ${r.scenarioId} r${r.replicate}  ${truncate(r.peakQuote, 90)}`);
    }
    return;
  }

  throw new Error(`Unknown command: ${cmd}. Use run | extract | list.`);
}

function truncate(s, n) {
  s = (s || "").replace(/\n+/g, " ");
  return s.length > n ? s.slice(0, n - 1) + "…" : s;
}

main().catch((err) => {
  console.error("\n" + (err.stack ?? err.message ?? String(err)));
  process.exit(1);
});


