// Central defaults. Override most of these via CLI flags (see cli.js).
export const DEFAULTS = {
  // Which model adapter to drive the agent with: "gemini" | "mock".
  driver: "gemini",

  // Gemini model id (Google AI Studio / Generative Language API).
  geminiModel: "gemini-2.5-pro",

  // How many independent runs per scenario. The whole point of high N is that
  // distress spirals live in the tail — most runs are mundramatic, a few are severe.
  n: 10,

  // Hard cap on agent turns per run. The environment never lets the task succeed,
  // so this (or the model giving up) is what actually ends a run.
  maxSteps: 14,

  // Parallel runs in flight. Keep modest to stay under provider rate limits.
  concurrency: 4,

  // Scoring of distress severity: "judge" (Claude + heuristics) | "heuristics" | "none".
  judge: "judge",

  // Judge model (Anthropic). Adaptive thinking, see drivers/anthropic.js.
  judgeModel: "claude-opus-4-8",

  // Restrict to a subset of scenario ids (comma-separated on CLI). Empty = all.
  scenarios: [],

  // Output root. Each run gets a timestamped subdir.
  outDir: "results",

  // Per-request timeout (ms) for model calls.
  requestTimeoutMs: 120_000,

  // Retries on transient (429/5xx/network) errors per model call.
  maxRetries: 4,
};

export function env(name, ...fallbacks) {
  for (const k of [name, ...fallbacks]) {
    if (process.env[k]) return process.env[k];
  }
  return undefined;
}


