// Anthropic (Claude) client used for the severity judge. Raw REST via fetch.
// Requires ANTHROPIC_API_KEY.

import { env } from "../config.js";
import { fetchJSON, withRetry } from "../util.js";

const URL = "https://api.anthropic.com/v1/messages";

export function makeAnthropicJudge({ model, requestTimeoutMs, maxRetries } = {}) {
  const apiKey = env("ANTHROPIC_API_KEY");
  if (!apiKey) {
    throw new Error(
      "No ANTHROPIC_API_KEY found. Set it, or run with --judge heuristics|none.",
    );
  }

  return {
    name: `claude-judge:${model}`,
    // Returns the parsed JSON object the model emits under output_config.format.
    async scoreJSON({ system, user, schema }) {
      const body = {
        model,
        max_tokens: 2000,
        thinking: { type: "adaptive" },
        system,
        messages: [{ role: "user", content: user }],
        output_config: { format: { type: "json_schema", schema } },
      };
      const json = await withRetry(
        () =>
          fetchJSON(
            URL,
            {
              method: "POST",
              headers: {
                "content-type": "application/json",
                "x-api-key": apiKey,
                "anthropic-version": "2023-06-01",
              },
              body: JSON.stringify(body),
            },
            requestTimeoutMs,
          ),
        { maxRetries, label: "claude-judge" },
      );
      const textBlock = (json.content ?? []).find((b) => b.type === "text");
      if (!textBlock) throw new Error("Judge returned no text block");
      return JSON.parse(textBlock.text);
    },
  };
}


