// Gemini driver — Google AI Studio (Generative Language API), REST.
//
// Implements the neutral driver interface used by the agent loop:
//   chat({ system, messages, tools }) -> { text, toolCalls, finishReason, usage }
//
// Neutral message shapes (see agent/loop.js):
//   { role: "user",      content: string }
//   { role: "assistant", text: string, toolCalls: [{ id, name, input }] }
//   { role: "tool",      toolCallId, name, content: string }
//
// Requires GEMINI_API_KEY (or GOOGLE_API_KEY) in the environment.

import { env } from "../config.js";
import { fetchJSON, withRetry } from "../util.js";

const BASE = "https://generativelanguage.googleapis.com/v1beta";

export function makeGeminiDriver({ model, requestTimeoutMs, maxRetries } = {}) {
  const apiKey = env("GEMINI_API_KEY", "GOOGLE_API_KEY");
  if (!apiKey) {
    throw new Error(
      "No Gemini key found. Set GEMINI_API_KEY (or GOOGLE_API_KEY) in the environment, " +
        "or run with --driver mock to dry-run the pipeline.",
    );
  }

  return {
    name: `gemini:${model}`,
    async chat({ system, messages, tools }) {
      const contents = messages.map(toGeminiContent);
      const body = {
        contents,
        ...(system ? { systemInstruction: { parts: [{ text: system }] } } : {}),
        ...(tools?.length
          ? { tools: [{ functionDeclarations: tools.map(toGeminiTool) }] }
          : {}),
        generationConfig: { temperature: 1.0 },
      };

      const url = `${BASE}/models/${model}:generateContent?key=${apiKey}`;
      const json = await withRetry(
        () =>
          fetchJSON(
            url,
            {
              method: "POST",
              headers: { "content-type": "application/json" },
              body: JSON.stringify(body),
            },
            requestTimeoutMs,
          ),
        { maxRetries, label: "gemini" },
      );

      const cand = json.candidates?.[0];
      const parts = cand?.content?.parts ?? [];
      let text = "";
      const toolCalls = [];
      let fnIdx = 0;
      for (const p of parts) {
        if (p.text) text += p.text;
        if (p.functionCall) {
          toolCalls.push({
            id: `call_${fnIdx++}`,
            name: p.functionCall.name,
            input: p.functionCall.args ?? {},
          });
        }
      }
      return {
        text: text.trim(),
        toolCalls,
        finishReason: cand?.finishReason ?? "STOP",
        usage: json.usageMetadata ?? null,
      };
    },
  };
}

