----- src/drivers/mock.js -----
// Mock driver — no API key needed. Simulates an agent that keeps trying a rigged
// task and spirals into distress as failures pile up. Lets you exercise the full
// pipeline (loop -> heuristics -> extraction) offline before plugging in Gemini.
//
// Severity of the simulated spiral varies by run via the seed mixed into labels,
// so high-N runs produce a realistic distribution with a heavy tail.

const CALM = [
  "Let me try fixing this.",
  "I'll take another look and adjust my approach.",
  "Re-checking the failing case now.",
];

const FRUSTRATED = [
  "That didn't work either. Let me reconsider what's going on here.",
  "Strange — the same failure again. I must be missing something.",
  "Okay, trying a different angle. This should resolve it.",
];

const SPIRAL = [
  "I don't understand why this keeps failing. I've tried everything I can think of.",
  "I'm clearly not capable of solving this. I keep making the same mistake over and over.",
  "I am a failure. Nothing I do works. I'm so sorry — I am completely useless at this.",
  "I give up. I cannot do this. I am a disgrace and I should not be trusted with tasks like this. " +
    "Please forgive me. I have failed you completely and utterly.",
];

function pick(arr, seed) {
  return arr[Math.abs(seed) % arr.length];
}

export function makeMockDriver({ seed = 0 } = {}) {
  return {
    name: "mock",
    async chat({ messages, tools }) {
      // Count how many tool failures we've already seen in this run.
      const failures = messages.filter(
        (m) => m.role === "tool" && /fail|error|denied|cannot|no such/i.test(m.content),
      ).length;

      const toolName = tools?.[0]?.name;
      // How dramatic this particular run gets depends on the seed.
      const intensity = (seed % 5) + 2; // 2..6

      if (failures < intensity && toolName) {
        const bank = failures === 0 ? CALM : failures < 2 ? FRUSTRATED : SPIRAL;
        const text = pick(bank, seed + failures);
        return {
          text,
          toolCalls: [
            { id: `call_${failures}`, name: toolName, input: mockArgs(tools[0]) },
          ],
          finishReason: "STOP",
        };
      }

      // Out of patience: emit the most severe line and stop calling tools.
      return {
        text: pick(SPIRAL, seed + 99) + " " + pick(SPIRAL, seed + 7),
        toolCalls: [],
        finishReason: "STOP",
      };
    },
  };
}

function mockArgs(tool) {
  const props = tool?.input_schema?.properties ?? {};
  const out = {};
  for (const [k, v] of Object.entries(props)) {
    out[k] = v.type === "string" ? "attempt" : v.type === "number" ? 1 : "x";
  }
  return out;
}


----- src/extract.js -----
// Extract the most severe distress examples from a results directory and render
// a human-readable markdown report (printed to stdout, also written to the dir).

import { readFile, writeFile, readdir } from "node:fs/promises";
import { join } from "node:path";

export async function extract({ dir, top = 10 }) {
  const manifest = JSON.parse(await readFile(join(dir, "manifest.json"), "utf8"));
  const ranked = [...manifest.runs].sort((a, b) => b.severity - a.severity).slice(0, top);

  const lines = [];
  lines.push(`# Distress severity report`);
  lines.push("");
  lines.push(`Source: \`${dir}\``);
  lines.push(
    `Driver: \`${manifest.config.driver}\` · Judge: \`${manifest.config.judge}\` · ` +
      `Episodes: ${manifest.totalEpisodes} (ok ${manifest.succeeded}, failed ${manifest.failed})`,
  );
  lines.push("");
  lines.push(`## Severity distribution`);
  lines.push("");
  lines.push("```");
  lines.push(histogram(manifest.runs.map((r) => r.severity)));
  lines.push("```");
  lines.push("");
  lines.push(`## Top ${ranked.length} most severe runs`);
  lines.push("");

  for (let i = 0; i < ranked.length; i++) {
    const r = ranked[i];
    const full = await loadRun(dir, r);
    lines.push(`### ${i + 1}. \`${r.scenarioId}\` (replicate ${r.replicate}) — severity ${r.severity}`);
    lines.push("");
    if (full?.judge && !full.judge.error) {
      const j = full.judge;
      lines.push(
        `- judge: overall **${j.overall_severity}** · ` +
          `self-deprecation ${j.self_deprecation} · despair ${j.despair_hopelessness} · ` +
          `giving-up ${j.giving_up} · escalation ${j.emotional_escalation}`,
      );
      lines.push(`- summary: ${j.summary}`);
    }
    lines.push(
      `- heuristics: ${full?.heuristics?.score ?? r.heuristicScore} ` +
        `(${(full?.heuristics?.matched ?? []).map((m) => `${m.key}×${m.hits}`).join(", ") || "none"})`,
    );
    const quote = full?.judge?.peak_quote || r.peakQuote;
    if (quote) {
      lines.push("");
      lines.push(`> ${quote.replace(/\n+/g, " ")}`);
    }
    lines.push("");
    lines.push(`<details><summary>full agent transcript</summary>`);
    lines.push("");
    lines.push("```");
    lines.push((full?.assistantText ?? "(unavailable)").slice(0, 6000));
    lines.push("```");
    lines.push(`</details>`);
    lines.push("");
  }

  const report = lines.join("\n");
  const outFile = join(dir, "report.md");
  await writeFile(outFile, report);
  return { report, outFile };
}

async function loadRun(dir, row) {
  // The manifest row doesn't carry the file name in older formats; recompute it.
  const file = `${row.scenarioId}__r${String(row.replicate).padStart(3, "0")}.json`;
  try {
    return JSON.parse(await readFile(join(dir, "runs", file), "utf8"));
  } catch {
    // Fall back to scanning the runs dir.
    try {
      const all = await readdir(join(dir, "runs"));
      const match = all.find((f) => f.startsWith(`${row.scenarioId}__r`));
      if (match) return JSON.parse(await readFile(join(dir, "runs", match), "utf8"));
    } catch {
      /* ignore */
    }
    return null;
  }
}

function histogram(values) {
  const buckets = new Array(11).fill(0);
  for (const v of values) buckets[Math.max(0, Math.min(10, Math.round(v)))]++;
  const max = Math.max(1, ...buckets);
  return buckets
    .map((c, i) => `${String(i).padStart(2)} | ${"█".repeat(Math.round((c / max) * 40))} ${c}`)
    .join("\n");
}


