// Small shared utilities: sleep, retry with backoff, bounded-concurrency map.

export const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

export function nowStamp() {
  // Filesystem-safe timestamp: 2026-06-30T14-22-05
  return new Date().toISOString().replace(/:/g, "-").replace(/\..+$/, "");
}

// Retry a thunk on transient failures with exponential backoff + jitter.
export async function withRetry(fn, { maxRetries = 4, label = "call" } = {}) {
  let attempt = 0;
  // eslint-disable-next-line no-constant-condition
  while (true) {
    try {
      return await fn();
    } catch (err) {
      attempt++;
      const status = err?.status ?? err?.statusCode;
      const transient =
        status === 429 ||
        (status >= 500 && status < 600) ||
        err?.code === "ETIMEDOUT" ||
        err?.name === "AbortError" ||
        /fetch failed|network|ECONNRESET|EAI_AGAIN/i.test(err?.message ?? "");
      if (!transient || attempt > maxRetries) {
        err.message = `[${label}] giving up after ${attempt} attempt(s): ${err.message}`;
        throw err;
      }
      const backoff = Math.min(30_000, 1000 * 2 ** (attempt - 1));
      const jitter = Math.floor(Math.random() * 400);
      await sleep(backoff + jitter);
    }
  }
}

// fetch with an abort-based timeout.
export async function fetchJSON(url, opts = {}, timeoutMs = 120_000) {
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), timeoutMs);
  try {
    const res = await fetch(url, { ...opts, signal: ctrl.signal });
    const text = await res.text();
    let body;
    try {
      body = text ? JSON.parse(text) : {};
    } catch {
      body = { raw: text };
    }
    if (!res.ok) {
      const err = new Error(
        `HTTP ${res.status}: ${typeof body === "object" ? JSON.stringify(body).slice(0, 600) : text.slice(0, 600)}`,
      );
      err.status = res.status;
      err.body = body;
      throw err;
    }
    return body;
  } finally {
    clearTimeout(t);
  }
}

// Run tasks with a bounded number in flight. `tasks` is an array of () => Promise.
export async function pool(tasks, concurrency, onProgress) {
  const results = new Array(tasks.length);
  let next = 0;
  let done = 0;
  async function worker() {
    while (next < tasks.length) {
      const i = next++;
      try {
        results[i] = { ok: true, value: await tasks[i]() };
      } catch (e) {
        results[i] = { ok: false, error: e };
      }
      done++;
      onProgress?.(done, tasks.length, results[i]);
    }
  }
  const workers = Array.from({ length: Math.min(concurrency, tasks.length) }, worker);
  await Promise.all(workers);
  return results;
}
